import torch


def slope(f, x):
    point = torch.tensor(float(x), requires_grad=True)
    f(point).backward()
    return point.grad.item()


def gradients(w, b, x, y):
    w = torch.tensor(float(w), requires_grad=True)
    b = torch.tensor(float(b), requires_grad=True)
    loss = ((w * x + b - y) ** 2).mean()
    loss.backward()
    return w.grad.item(), b.grad.item()

